<?php
defined('ABSPATH') || exit;

/** Deterministic, evidence-bearing suggestions; never a claim of independent review. */
final class CAFCC_Search_Tags {
    public static function table(){global $wpdb;return $wpdb->prefix.'cafcc_academic_search_tags';}
    public static function catalog(){static $v=null;if($v===null)$v=json_decode(file_get_contents(dirname(__DIR__).'/data/standards-reference.json'),true);return $v;}
    public static function normalise($s){$s=strtolower(remove_accents($s));$s=preg_replace('/\bsecuriti[sz]ation\b/','securitisation',$s);$s=preg_replace('/\bind[\s._-]*as\b/i','ind as',$s);$s=preg_replace('/\bind[\s._-]*as[\s._-]*(\d+)/i','ind as $1',$s);$s=preg_replace('/\bsa[\s._-]*(\d+)/i','sa $1',$s);return trim(preg_replace('/[^a-z0-9]+/',' ',$s));}
    public static function suggest($d,$manual=array()){
        $out=array();$add=function($label,$kind,$method,$evidence)use(&$out){$label=sanitize_text_field($label);$key=self::normalise($label);if(!$key||strlen($label)>190||CAFCC_Bank_DB::private_reference($label))return;$out[$key]=array('label'=>$label,'normalised'=>$key,'kind'=>$kind,'origin'=>$method,'evidence'=>sanitize_text_field($evidence),'academic_verification'=>'not_independently_verified');};
        $names=array();foreach($d['classification']??array() as $id){$n=CAFCC_Academic::get('taxonomy',$id);if(!$n)continue;foreach(CAFCC_Explorer::ancestors($n) as $aid){$p=CAFCC_Academic::get('taxonomy',$aid);if(in_array($p['node_type'],array('topic','subtopic','chapter','unit'),true)){$names[]=$p['title'];$add($p['title'],'topic','imported_mapping','Edition-specific proposed path; not independent verification.');}}}
        foreach(array_slice($d['ai_proposal']['proposed_search_tags']??array(),0,20)as $label){if(!is_string($label)||strlen($label)>190||CAFCC_Bank_DB::private_reference($label))continue;$valid=true;if(preg_match_all('/\b(?:Ind\s*AS|SA)\s*\d+/i',$label,$refs))foreach($refs[0]as $ref){$known=false;foreach(self::catalog()['entries']as $entry)if(self::normalise($entry['code'])===self::normalise($ref))$known=true;if(!$known)$valid=false;}if($valid)$add($label,'concept','source_evidence_proposal','Source-heading, printed statutory reference or precisely scoped prior-correction proposal. Editorial, provisional and separate from official syllabus nodes.');}
        $primary=$names[0]??($d['subject_code'].' — Topic to be refined');$add($primary,'primary','editorial_fallback','Transparent provisional navigation label.');
        $q=html_entity_decode(wp_strip_all_tags($d['rich_content']['question']['body_html']??''),ENT_QUOTES|ENT_HTML5,'UTF-8');$a=html_entity_decode(wp_strip_all_tags($d['rich_content']['answer']['body_html']??''),ENT_QUOTES|ENT_HTML5,'UTF-8');$path=implode(' ',$names);$combined=$q.' '.$a.' '.$path;
        $rules=array('Ind AS 109'=>'effective interest|amortised cost|expected credit loss|embedded derivatives?|hedg(?:e|ing) accounting','Ind AS 110'=>'consolidated (?:balance sheet|financial statements)|consolidation|non.controlling interest','Ind AS 103'=>'business combinations?|acquisition.date (?:measurement|goodwill)|goodwill on acquisition','Ind AS 113'=>'fair value hierarchy|highest and best use|valuation techniques?|principal market','Ind AS 115'=>'revenue recognition|performance obligations?|transaction price|revenue from contracts','Ind AS 116'=>'right.of.use asset|lease liability','Ind AS 102'=>'share.based payment','Ind AS 21'=>'functional currency|foreign (?:exchange|currency) translation','Ind AS 8'=>'prior.period error|change in accounting polic','Ind AS 16'=>'property,? plant and equipment|revaluation model|depreciation of','Ind AS 40'=>'investment propert','SA 200'=>'overall objectives of the independent auditor|reasonable assurance and professional (?:scepticism|skepticism)','SA 240'=>'fraud|management override','SA 320'=>'materiality','SA 520'=>'analytical procedures');
        foreach(self::catalog()['entries'] as $entry){if($d['subject_code']!==$entry['subject']&&$d['subject_code']!=='IBS')continue;$code=$entry['code'];$regex=$entry['family']==='SA'?'\bSA\s*'.$entry['number'].'\b':'\bInd\s*AS\s*'.$entry['number'].'\b';$explicit=preg_match('/'.$regex.'/i',$combined);$inferred=isset($rules[$code])&&preg_match('/'.$rules[$code].'/i',$q.' '.$path);if(!$explicit&&!$inferred)continue;$add($code,'standard',$explicit?'explicit_reference':'rule_assisted_inference',$explicit?'Recognised standard reference in question, proposed path or candidate answer.':'Supported concept pattern; provisional inference.');$add($entry['title'],'standard_name','catalogue_alias',$code.' — official naming catalogue; applicability remains edition-specific.');}
        foreach(array('Goodwill'=>'goodwill','Non-controlling interests'=>'non.controlling','Acquisition-date measurement'=>'acquisition.date','Embedded Derivatives'=>'embedded derivatives?','Yield to Maturity'=>'yield to maturity','Professional ethics'=>'professional ethics|ethical (?:issue|dilemma)|independence threat','Materiality'=>'materiality','Financial Instruments'=>'financial instruments?|amortised cost|embedded derivatives?') as $label=>$rule)if(preg_match('/'.$rule.'/i',$combined))$add($label,'concept','rule_assisted_inference','Concept evidence; editorial search tag.');
        foreach($manual as $label){if(!is_string($label)||strlen($label)>190||CAFCC_Bank_DB::private_reference($label))return CAFCC_Repository::error('Use short public academic tags, without private links.');if(preg_match('/\b(?:Ind\s*AS|SA)\s*\d+/i',$label,$m)){ $code=preg_replace('/\s+/',' ',trim($m[0]));$known=false;foreach(self::catalog()['entries'] as $e)if(self::normalise($e['code'])===self::normalise($code))$known=true;if(!$known)return CAFCC_Repository::error('Unknown Ind AS/SA number. Choose a standard from the reference catalogue.');}$add($label,'owner_tag','owner_correction','Saved by the administrator, separately from official syllabus headings.');}
        return array_slice(array_values($out),0,100);
    }
    public static function save($r,$manual=null){
        if(!CAFCC_Repository::admin_allowed())return CAFCC_Repository::error('Administrator required.',403);
        global $wpdb;$t=self::table();$old=$wpdb->get_col($wpdb->prepare("SELECT label FROM $t WHERE review_id=%d AND origin='owner_correction'",$r['id']));$tags=self::suggest($r['data'],$manual===null?$old:$manual);if(is_wp_error($tags))return $tags;$override=$manual!==null||!empty($r['owner_tags_override']);if($override){$tags=array_values(array_filter($tags,function($t){return $t['origin']==='owner_correction'||in_array($t['kind'],array('topic','primary'),true);}));if(false===$wpdb->update(CAFCC_Studio::table(),array('owner_tags_override'=>1),array('id'=>$r['id'])))return CAFCC_Repository::error('Cannot retain the owner tag override.',500);}
        $wpdb->delete($t,array('review_id'=>$r['id']));foreach($tags as $v){$v=array_merge($v,array('review_id'=>$r['id'],'question_id'=>(int)($r['question_id']??0),'catalogue_version'=>self::catalog()['version']));unset($v['academic_verification']);if(false===$wpdb->insert($t,$v))return CAFCC_Repository::error('Could not save academic search tags.',500);}return $tags;
    }
    public static function for_review($id){global $wpdb;return $wpdb->get_results($wpdb->prepare('SELECT label,kind,origin FROM '.self::table().' WHERE review_id=%d ORDER BY id',$id),ARRAY_A);}
    public static function standard_query($term){return (bool)preg_match('/^(?:sa|ind as)(?: \d+)?$/D',self::normalise($term));}
    public static function predicate($alias,$term,&$args){global $wpdb;$normal=self::normalise($term);$aliases=array('revenue recognition'=>'revenue from contracts with customers','financial instrument'=>'financial instruments','held for sale'=>'non current assets held for sale and discontinued operations');$normal=$aliases[$normal]??$normal;if(self::standard_query($term)){$args[]=$normal;$args[]=$wpdb->esc_like($normal).' %';return "($alias.kind IN ('standard','owner_tag') AND ($alias.normalised=%s OR $alias.normalised LIKE %s))";}$args[]='%'.$wpdb->esc_like($normal).'%';return "$alias.normalised LIKE %s";}
    public static function search_sql($qid,$term,&$args){return 'EXISTS(SELECT 1 FROM '.self::table()." academic_search WHERE academic_search.question_id=$qid AND ".self::predicate('academic_search',$term,$args).')';}
}
